// A photo thumbnail (job condition photos, a customer's uploaded slip, expense receipts, ...) that opens the full
// image in the Lightbox popup below instead of navigating to a new tab/page.
function PhotoThumb({id,alt,onOpen}:{id:string;alt:string;onOpen:(id:string)=>void}){return <button type="button" className="photo-thumb" onClick={()=>onOpen(id)} aria-label={'ดูรูปขยาย: '+alt}><img src={'/api/files/'+id} alt={alt}/></button>}
// The popup itself: one image over a dim backdrop, closed by its own button, Escape, or clicking outside the image.
// Portaled straight to <body> so it always stacks above an open Dialog (whose own overlay/content are portaled
// there too) - a photo is often opened from inside one (job detail, payment, expense gallery).
function Lightbox({id,onClose}:{id:string|null;onClose:()=>void}){
  useEffect(()=>{if(!id)return;const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose()};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[id,onClose]);
  if(!id)return null;
  // A photo is usually opened from inside a Dialog (job detail, payment, expense gallery). Since this popup is a
  // separate portal, not nested inside that Dialog's own DOM, Radix's "click outside closes the dialog" listener
  // (attached to the document, capture phase) would otherwise see every click here as "outside" and dismiss the
  // Dialog underneath too - stopping the pointerdown in the capture phase keeps it from ever reaching that listener.
  return createPortal(<div className="lightbox-overlay" role="dialog" aria-modal="true" aria-label="ดูรูปขยาย" onPointerDownCapture={e=>e.stopPropagation()} onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}>
    <img src={'/api/files/'+id} alt=""/>
    <button type="button" className="lightbox-close" aria-label="ปิด" onClick={onClose}><CircleX size={22}/></button>
  </div>,document.body);
}
