{(modal==='checkout'||modal==='payJob')&&<div className={'pay-body'+(payWide?' with-qr':'')}><div className="payment-total">฿{fmt(modal==='checkout'?total:selected?.amount||0)}</div>{modal==='payJob'&&selected?.reward_used===1&&<div className="reward-notice"><Gift size={18}/><span>{selected.amount===0?'ใช้สิทธิ์สมาชิก · ขึ้นเอ็นฟรี':'ใช้สิทธิ์สมาชิก · ลด ฿'+fmt(selected.reward_discount||0)}</span></div>}<Field label="วิธีชำระเงิน"><Choice value={method} onChange={setMethod} options={['โอนเงิน','เงินสด','บัตร']}/></Field>{method==='โอนเงิน'&&<BankTransfer config={data.config}/>}{modal==='payJob'&&selected?.slip&&form.slip===selected.slip?<div className="notice customer-slip"><p><b>ลูกค้าแนบสลิปมาจากหน้าติดตามสถานะ</b> กรุณาตรวจสอบยอดก่อนยืนยัน</p><div className="customer-slip-actions"><button type="button" className="text-button" onClick={()=>setLightbox(form.slip)}>ดูสลิปที่ลูกค้าแนบ</button><label className="attach-button secondary small"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>upload(e.target.files,'slip')}/>แนบสลิปใหม่แทน</label></div></div>:<><Field label="แนบสลิป (ถ้ามี)"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>upload(e.target.files,'slip')}/></Field>{form.slip&&<p className="paid">แนบสลิปแล้ว ✓ <button type="button" className="text-button" onClick={()=>setLightbox(form.slip)}>ดูสลิป</button></p>}</>}<p className="muted">ตรวจสอบว่าได้รับเงินจริงก่อนยืนยัน สลิปที่แนบไม่ได้ตรวจยอดโอนอัตโนมัติ</p>{modal==='checkout'&&<Field className="member-optional" label="สมาชิก (ไม่บังคับ)"><MemberPicker jobs={jobs} sales={data.sales||[]} config={data.config} value={form.member} onChange={(member:any)=>setForm({...form,member:member||undefined})} total={total}/></Field>}</div>}
